// Loop over input items to separate Google and YouTube results
const googleResults = items.find(item => item.json.search_parameters && item.json.search_parameters.engine === 'google');
const youtubeResults = items.find(item => item.json.search_parameters && item.json.search_parameters.engine === 'youtube');

// Dynamically extract the topic from the search parameters
// We prefer the Google query 'q', but fall back to YouTube 'search_query' if needed
let topic = "Unknown Topic";
if (googleResults && googleResults.json.search_parameters.q) {
  topic = googleResults.json.search_parameters.q;
} else if (youtubeResults && youtubeResults.json.search_parameters.search_query) {
  topic = youtubeResults.json.search_parameters.search_query;
}

// Prepare the consolidated data object
const consolidatedData = {
  topic: topic,
  google: {
    total_results: googleResults ? googleResults.json.search_information.total_results : 0,
    organic_results: googleResults ? googleResults.json.organic_results : [],
    // You can add more Google fields here if needed
  },
  youtube: {
    total_results: youtubeResults ? youtubeResults.json.search_information.total_results : 0,
    video_results: youtubeResults ? youtubeResults.json.video_results : [],
    shorts_results: youtubeResults ? youtubeResults.json.shorts_results : []
  },
  google_total: googleResults ? googleResults.json.search_information.total_results : 0,
  youtube_total: youtubeResults ? youtubeResults.json.search_information.total_results : 0
};

// Return the data in the specific format requested
// Note: We stringify 'consolidated_serp' because your output example showed it as a string
return [
  {
    json: {
      topic: topic,
      consolidated_serp: JSON.stringify(consolidatedData, null, 2)
    }
  }
];

const results = [];
// Ensure 'Get row(s) in sheet' is the correct node name in your workflow
const sourceItems = $('Get row(s) in sheet').all(); 

for (const item of items) {
  const text = item.json.text || "";

  // Link back to original row
  const sourceItem = sourceItems[item.index] || sourceItems[0];
  const rowNum = sourceItem.json.row_number || ""; 
  const searchQuery = sourceItem.json["Search Query"] || sourceItem.json.topic || "Unknown";

  // ----------------------------------------------------------------------
  // 1. UNIVERSAL FIELD EXTRACTOR
  // ----------------------------------------------------------------------
  const getSubField = (sectionNum, fieldLabelRegex) => {
    const pattern = `### ${sectionNum}\\.[\\s\\S]*?(?:\\*|\\-)\\s*(?:\\*\\*)?(${fieldLabelRegex})(?:\\*\\*)?:\\s*(.*)`;
    const regex = new RegExp(pattern, "i");
    const match = text.match(regex);

    if (match && match[2]) {
      // Clean up the result (remove trailing markdown like quotes or brackets)
      return match[2].split('\n')[0].replace(/[`"()]/g, '').trim();
    }
    return "";
  };

  // ----------------------------------------------------------------------
  // 2. UNIVERSAL TIER SUMMARY EXTRACTOR
  // ----------------------------------------------------------------------
  const getTierSummary = (tierNum) => {
    const sections = text.split(/\*\*\s*Tier\s*\d*\s*Summary:\s*\*\*/i);

    if (sections[tierNum]) {
      let content = sections[tierNum];
      // Cut off at the next major section (---, ## VERDICT, or ## TIER)
      content = content.split(/---|##\s*VERDICT|##\s*TIER/i)[0];
      return content.trim();
    }
    return "";
  };

  // ----------------------------------------------------------------------
  // 3. UNIVERSAL VERDICT EXTRACTOR
  // ----------------------------------------------------------------------
  const getVerdict = (key) => {
    const regex = new RegExp(`(?:\\*|\\-)\\s*\\*\\*${key}:\\*\\*\\s*(.*)`, "i");
    const match = text.match(regex);
    return match ? match[1].replace(/[`"()]/g, '').trim() : "";
  };

  results.push({
    json: {
      "row_number": rowNum,
      "search_query": searchQuery,

      "tier1_opportunity": {
        "video_deficit": { 
            "ratio": getSubField(1, "(?:Ratio|Calculation)").replace('~', ''), 
            "signal": getSubField(1, "Signal") 
        },
        "distress_signal": { "level": getSubField(2, "Level"), "evidence": getSubField(2, "Evidence") },
        "david_vs_goliath": { "level": getSubField(3, "(?:Level|Count)"), "evidence": getSubField(3, "Evidence") },
        "tier_summary": getTierSummary(1)
      },

      "tier2_positioning": {
        "implementation_gap": { "level": getSubField(4, "Level"), "recommendation": getSubField(4, "Recommendation") },
        "authority_dominance": { "type": getSubField(5, "Type"), "recommendation": getSubField(5, "Recommendation") },
        "topic_freshness": { "status": getSubField(6, "Status"), "avg_age_days": getSubField(6, "Average Age").replace(/\D/g, '') },
        "contrarian_potential": { "opportunity": getSubField(7, "Opportunity"), "suggested_angle": getSubField(7, "Suggested Angle") },
        "tier_summary": getTierSummary(2)
      },

      "tier3_execution": {
        "velocity_signal": { 
            "winning_format": getSubField(8, "Winning Format"), 
            "top_video_title": getSubField(8, "Top Video(?: Title)?"), 
            "top_video_length": getSubField(8, "(?:Top Video )?Length") 
        },
        "format_void": { "missing": getSubField(9, "(?:Category )?Void"), "suggestion": getSubField(9, "Suggestion") },
        // Metric 10 (Money Shot) removed here
        "tier_summary": getTierSummary(3)
      },

      "verdict": {
        "make_video": getVerdict("make_video") === 'true',
        "confidence": parseFloat(getVerdict("confidence")),
        "recommended_title_angle": getVerdict("recommended_title_angle"),
        "recommended_format": getVerdict("recommended_format"),
        "reasoning": getVerdict("reasoning")
      }
    }
  });
}

return results;

